-- Local-only standalone snapshots; no project moderation or retention policy.
CREATE TABLE project_drafts(id TEXT PRIMARY KEY,owner_account_id TEXT NOT NULL REFERENCES private_accounts(id) ON DELETE CASCADE,title TEXT NOT NULL,description TEXT NOT NULL,github_url TEXT NOT NULL,demo_url TEXT NOT NULL,version INTEGER NOT NULL CHECK(version BETWEEN 1 AND 9007199254740991),updated_at_ms INTEGER NOT NULL);
CREATE INDEX project_drafts_owner_recent ON project_drafts(owner_account_id,updated_at_ms DESC,id ASC);
CREATE TABLE project_publications(id TEXT PRIMARY KEY,owner_account_id TEXT REFERENCES private_accounts(id) ON DELETE SET NULL,draft_id TEXT UNIQUE REFERENCES project_drafts(id) ON DELETE SET NULL,public_profile_id TEXT NOT NULL REFERENCES public_profiles(id),source_version INTEGER NOT NULL CHECK(source_version BETWEEN 1 AND 9007199254740991),title TEXT NOT NULL,description TEXT NOT NULL,github_url TEXT NOT NULL,demo_url TEXT NOT NULL,published_at_ms INTEGER NOT NULL CHECK(published_at_ms BETWEEN 0 AND 253402300799999),status TEXT NOT NULL CHECK(status IN ('published','hidden','deleted')));
CREATE INDEX project_publications_author_recent ON project_publications(public_profile_id,published_at_ms DESC,id ASC);
